"""Compressed byte-sequence representation for the payload extension.

Sequences are kept as a shared DAG (rope) so that very large logical byte
strings and repeated boundary probes never need to be materialised.  Every
node knows its exact length and its exact fingerprint, which makes the
checksum computation independent of the expanded size.

Supported expression syntax (see PROTOCOL.md):

* unicode string or bytes literals,
* nonnegative integer literals ``<= 2**63-1``,
* names of earlier definitions,
* parentheses,
* concatenation ``+`` of byte sequences,
* repetition ``*`` of one byte sequence by one integer (either order),
* byte slices ``[lo:hi]`` with either endpoint optionally omitted.
"""
import ast
import hashlib
import re

MAX = (1 << 63) - 1

_MOD = 1 << 64
_MASK = _MOD - 1
_BASE = 257
_MAX_DEPTH = 128

IDENTIFIER = re.compile(r'[A-Za-z][A-Za-z0-9_]{0,31}\Z', re.ASCII)
RANDOM_MARK = '<<random_string>>'


# --------------------------------------------------------------------------
# rope nodes
# --------------------------------------------------------------------------
class Leaf(object):
    """A literal run of bytes."""

    __slots__ = ('data', 'length', 'hash', 'weight', 'has_lf')

    kind = 0

    def __init__(self, data):
        self.data = data
        self.length = len(data)
        value = 0
        for byte in data:
            value = (value * _BASE + byte + 1) & _MASK
        self.hash = value
        self.weight = 1 if data else 0
        self.has_lf = b'\n' in data


class Rep(object):
    """``count`` repetitions of ``child``."""

    __slots__ = ('child', 'count', 'length', 'hash', 'weight', 'has_lf')

    kind = 1

    def __init__(self, child, count):
        self.child = child
        self.count = count
        self.length = child.length * count
        value = child.hash * geo_sum(pow(_BASE, child.length, _MOD), count)
        self.hash = value & _MASK
        self.weight = 1
        self.has_lf = child.has_lf


class Cat(object):
    """Concatenation of two ropes."""

    __slots__ = ('left', 'right', 'length', 'hash', 'weight', 'has_lf')

    kind = 2

    def __init__(self, left, right):
        self.left = left
        self.right = right
        self.length = left.length + right.length
        value = left.hash * pow(_BASE, right.length, _MOD) + right.hash
        self.hash = value & _MASK
        self.weight = left.weight + right.weight
        self.has_lf = left.has_lf or right.has_lf


EMPTY = Leaf(b'')


def geo_sum(ratio, count):
    """``sum(ratio**j for j in range(count))`` modulo ``2**64``."""
    result_power = 1
    result_sum = 0
    block_power = ratio
    block_sum = 1
    while count:
        if count & 1:
            result_sum = (result_sum + result_power * block_sum) & _MASK
            result_power = (result_power * block_power) & _MASK
        block_sum = (block_sum + block_power * block_sum) & _MASK
        block_power = (block_power * block_power) & _MASK
        count >>= 1
    return result_sum


def leaf(data):
    """A literal byte run."""
    if not data:
        return EMPTY
    return Leaf(data)


def literal(data):
    """Compatibility helper: literal bytes."""
    return leaf(data)


def size(node):
    """Logical length of a rope."""
    return node.length if node is not None else 0


def concat(left, right):
    """Concatenate two ropes, keeping the result weight balanced."""
    return merge(left, right)


def merge(left, right):
    """Weight balanced concatenation of two ropes."""
    if left is None or left.weight == 0:
        return right
    if right is None or right.weight == 0:
        return left
    if left.weight >= right.weight:
        if left.kind == Cat.kind:
            return balance(left.left, merge(left.right, right))
        return Cat(left, right)
    if right.kind == Cat.kind:
        return balance(merge(left, right.left), right.right)
    return Cat(left, right)


def balance(left, right):
    """Restore the weight balance invariant of a concatenation."""
    if left is None or left.weight == 0:
        return right
    if right is None or right.weight == 0:
        return left
    if left.weight > 3 * right.weight:
        return Cat(left.left, balance(left.right, right))
    if right.weight > 3 * left.weight:
        return Cat(balance(left, right.left), right.right)
    return Cat(left, right)


def repeat(node, count):
    """Repeat a rope ``count`` times."""
    if node is None or count <= 0 or node.length == 0:
        return EMPTY
    if count == 1:
        return node
    if node.kind == Rep.kind:
        return Rep(node.child, node.count * count)
    return Rep(node, count)


def cut(node, start, end):
    """Return the byte range ``[start:end)`` of a rope."""
    if node is None:
        return EMPTY
    if start < 0 or end < start or end > node.length:
        raise ValueError('slice range')
    if start == 0 and end == node.length:
        return node
    if node.length == 0:
        return EMPTY
    if node.kind == Leaf.kind:
        return Leaf(node.data[start:end])
    if node.kind == Rep.kind:
        unit = node.child.length
        first = start // unit
        last = (end - 1) // unit
        if first == last:
            offset = start - first * unit
            return cut(node.child, offset, offset + (end - start))
        parts = []
        head = start - first * unit
        if head:
            parts.append(cut(node.child, head, unit))
        middle = last - first - 1
        if middle > 0:
            parts.append(repeat(node.child, middle))
        tail = end - last * unit
        if tail:
            parts.append(cut(node.child, 0, tail))
        result = parts[0]
        for part in parts[1:]:
            result = merge(result, part)
        return result
    left = node.left.length
    if end <= left:
        return cut(node.left, start, end)
    if start >= left:
        return cut(node.right, start - left, end - left)
    return merge(cut(node.left, start, left), cut(node.right, 0, end - left))


def materialize(node, limit=65536):
    """Expand a bounded rope into bytes."""
    if node is None:
        return b''
    if node.length > limit:
        raise ValueError('bounded materialization')
    out = bytearray()
    _fill(node, out)
    return bytes(out)


def _fill(node, out):
    if node.kind == Leaf.kind:
        out += node.data
    elif node.kind == Rep.kind:
        for _ in range(node.count):
            _fill(node.child, out)
    else:
        _fill(node.left, out)
        _fill(node.right, out)


def read_range(node, start, end):
    """Expand the byte range ``[start:end)`` of a rope."""
    if node is None or end <= start:
        return b''
    if node.length > (1 << 40):
        raise ValueError('bounded materialization')
    out = bytearray()
    _read(node, start, end, out)
    return bytes(out)


def _read(node, start, end, out):
    if end <= start:
        return
    if node.kind == Leaf.kind:
        out += node.data[start:end]
        return
    if node.kind == Rep.kind:
        unit = node.child.length
        first = start // unit
        last = (end - 1) // unit
        if first == last:
            offset = start - first * unit
            _read(node.child, offset, offset + (end - start), out)
            return
        head = start - first * unit
        if head:
            _read(node.child, head, unit, out)
        for index in range(first + 1, last):
            _fill(node.child, out)
        tail = end - last * unit
        if tail:
            _read(node.child, 0, tail, out)
        return
    left = node.left.length
    if end <= left:
        _read(node.left, start, end, out)
        return
    if start >= left:
        _read(node.right, start - left, end - left, out)
        return
    _read(node.left, start, left, out)
    _read(node.right, 0, end - left, out)


def fingerprint(node):
    """Exact fingerprint ``{"n":N,"h":"hhhhhhhhhhhhhhhh"}`` of a rope."""
    if node is None:
        return {'n': 0, 'h': '%016x' % 0}
    return {'n': node.length, 'h': '%016x' % node.hash}


def fingerprint_bytes(data):
    """Exact fingerprint of a byte string."""
    value = 0
    for byte in data:
        value = (value * _BASE + byte + 1) & _MASK
    return {'n': len(data), 'h': '%016x' % value}


def prefix_hash(node, count):
    """Exact checksum of the first ``count`` bytes of a rope."""
    if node is None or count <= 0:
        return 0
    if count >= node.length:
        return node.hash
    if node.kind == Leaf.kind:
        value = 0
        for byte in node.data[:count]:
            value = (value * _BASE + byte + 1) & _MASK
        return value
    if node.kind == Rep.kind:
        unit = node.child.length
        whole = count // unit
        rest = count % unit
        value = node.child.hash * geo_sum(pow(_BASE, unit, _MOD), whole)
        value &= _MASK
        if rest:
            value = (value * pow(_BASE, rest, _MOD) + prefix_hash(node.child, rest)) & _MASK
        return value
    left = node.left.length
    if count <= left:
        return prefix_hash(node.left, count)
    value = node.left.hash * pow(_BASE, count - left, _MOD)
    return (value + prefix_hash(node.right, count - left)) & _MASK


def hash_range(node, start, end):
    """Exact checksum of the byte range ``[start:end)`` of a rope."""
    if node is None or end <= start:
        return 0
    high = prefix_hash(node, end)
    low = prefix_hash(node, start)
    return (high - low * pow(_BASE, end - start, _MOD)) & _MASK


def next_lf(node, start=0):
    """Index of the next LF byte at or after ``start`` (-1 when absent)."""
    if node is None:
        return -1
    found = _next_lf(node, start)
    return -1 if found < 0 else found


def _next_lf(node, start):
    if start < 0:
        start = 0
    if start >= node.length or not node.has_lf:
        return -1
    if node.kind == Leaf.kind:
        return node.data.find(b'\n', start)
    if node.kind == Rep.kind:
        unit = node.child.length
        index = start // unit
        offset = start - index * unit
        found = _next_lf(node.child, offset)
        if found >= 0:
            return index * unit + found
        index += 1
        if index >= node.count:
            return -1
        found = _next_lf(node.child, 0)
        if found < 0:
            return -1
        return index * unit + found
    left = node.left.length
    if start < left:
        found = _next_lf(node.left, start)
        if found >= 0:
            return found
        found = _next_lf(node.right, 0)
        return -1 if found < 0 else left + found
    found = _next_lf(node.right, start - left)
    return -1 if found < 0 else left + found


# --------------------------------------------------------------------------
# expression evaluation
# --------------------------------------------------------------------------
def ast_depth(node):
    """Maximum AST nesting depth, the root expression body counting as zero."""
    stack = [(node, 0)]
    deepest = 0
    while stack:
        current, depth = stack.pop()
        if depth > deepest:
            deepest = depth
        for child in ast.iter_child_nodes(current):
            stack.append((child, depth + 1))
    return deepest


def parse_expression(source):
    """Parse an expression source with CPython's own parser."""
    if type(source) is not str:
        raise ValueError('expression type')
    try:
        tree = ast.parse(source, mode='eval')
    except (SyntaxError, ValueError, MemoryError, RecursionError):
        raise ValueError('expression syntax')
    if ast_depth(tree.body) > _MAX_DEPTH:
        raise ValueError('expression depth')
    return tree.body


class Context(object):
    """Named byte expressions plus the template compiler."""

    def __init__(self, definitions, seed):
        self.seed = seed
        self.definitions = definitions
        self.values = {}
        for name, expression in definitions:
            if type(name) is not str or IDENTIFIER.match(name) is None:
                raise ValueError('definition name')
            if name in self.values:
                raise ValueError('duplicate definition')
            node = self.evaluate(expression, self.values)
            if isinstance(node, int):
                raise ValueError('definition type')
            self.values[name] = node

    # -- expressions ------------------------------------------------------
    def evaluate(self, source, environment=None):
        """Evaluate an expression source into a rope or an integer."""
        body = parse_expression(source)
        return self._eval(body, self.values if environment is None else environment)

    def _eval(self, node, environment):
        kind = type(node)
        if kind is ast.Constant:
            value = node.value
            if value is None or isinstance(value, bool):
                raise ValueError('constant type')
            if isinstance(value, int):
                if value < 0 or value > MAX:
                    raise ValueError('integer range')
                return value
            if isinstance(value, str):
                try:
                    return Leaf(value.encode('utf8'))
                except UnicodeEncodeError:
                    raise ValueError('string encoding')
            if isinstance(value, bytes):
                return Leaf(value)
            raise ValueError('constant type')
        if kind is ast.Name:
            if node.id not in environment:
                raise ValueError('unknown name')
            return environment[node.id]
        if kind is ast.BinOp:
            operation = type(node.op)
            if operation is ast.Add:
                left = self._eval(node.left, environment)
                right = self._eval(node.right, environment)
                if isinstance(left, int) or isinstance(right, int):
                    raise ValueError('addition type')
                return merge(left, right)
            if operation is ast.Mult:
                left = self._eval(node.left, environment)
                right = self._eval(node.right, environment)
                left_int = isinstance(left, int)
                right_int = isinstance(right, int)
                if left_int == right_int:
                    raise ValueError('multiplication type')
                if left_int:
                    count = left
                    sequence = right
                else:
                    count = right
                    sequence = left
                if count < 0 or count > MAX:
                    raise ValueError('repetition count')
                if sequence.length * count > MAX:
                    raise ValueError('length overflow')
                return repeat(sequence, count)
            raise ValueError('operator')
        if kind is ast.Subscript:
            value = self._eval(node.value, environment)
            if isinstance(value, int):
                raise ValueError('slice type')
            bounds = node.slice
            if type(bounds) is not ast.Slice or bounds.step is not None:
                raise ValueError('slice form')
            low = 0 if bounds.lower is None else self._endpoint(bounds.lower)
            high = value.length if bounds.upper is None else self._endpoint(bounds.upper)
            if low < 0 or high < low or high > value.length:
                raise ValueError('slice range')
            return cut(value, low, high)
        raise ValueError('expression syntax')

    @staticmethod
    def _endpoint(node):
        if type(node) is not ast.Constant:
            raise ValueError('slice endpoint')
        value = node.value
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError('slice endpoint')
        if value < 0 or value > MAX:
            raise ValueError('slice endpoint')
        return value

    # -- templates --------------------------------------------------------
    def template(self, value, coordinate):
        """Compile one template string into a rope."""
        if type(value) is not str:
            raise ValueError('template type')
        if value.startswith('{{') and value.endswith('}}'):
            source = value[2:-2].strip()
            result = self.evaluate(source)
            if isinstance(result, int):
                raise ValueError('template type')
            return result
        text = value
        if RANDOM_MARK in text:
            pieces = text.split(RANDOM_MARK)
            rebuilt = [pieces[0]]
            for index in range(len(pieces) - 1):
                rebuilt.append(self.random_string(coordinate, index))
                rebuilt.append(pieces[index + 1])
            text = ''.join(rebuilt)
        try:
            return Leaf(text.encode('utf8'))
        except UnicodeEncodeError:
            raise ValueError('string encoding')

    def random_string(self, coordinate, occurrence):
        """Deterministic replacement text for one ``<<random_string>>``."""
        payload = '%s/%s/%d' % (self.seed, coordinate, occurrence)
        digest = hashlib.sha256(payload.encode('utf8')).hexdigest()
        return digest[:20]
